    virginMaiTai: { name: "Mai tai sans alcool", steps: ["Secoue les jus, le citron vert, l'orgeat et la grenadine avec des glaçons.", "Verse sur de la glace pilée, un brin de menthe."] },
    dernierMetro: { name: "Dernier métro", steps: ["Secoue le bourbon, l'amaretto, le citron et le miel avec des glaçons.", "Filtre sur un gros glaçon, à boire avant de courir."] },
    tourneeGenerale: { name: "Tournée générale", steps: ["Mélange l'apéritif, le vin blanc et le jus d'orange dans une carafe pleine de glaçons.", "Complète à l'eau gazeuse et sers un verre à chacun, une rondelle d'orange."] },
    nuitBlanche: { name: "Nuit blanche", steps: ["Secoue la vodka, la liqueur de sureau, le citron et le blanc d'œuf sans glace.", "Secoue encore avec des glaçons et filtre dans une coupe."] },
    apresMinuit: { name: "Après minuit", steps: ["Secoue le rhum, la liqueur de café, le café et la vanille avec des glaçons.", "Filtre dans une coupe froide."] },
    toastDuCrew: { name: "Toast du crew", steps: ["Verse le gin, le sirop de sureau et le citron dans une flûte.", "Complète au prosecco et lève ton verre."] },
    leveDuJour: { name: "Lever du jour", steps: ["Verse la tequila, l'orange et la passion sur des glaçons.", "Laisse couler la grenadine au fond, pour l'aube."] },
    apresLeConcert: { name: "Après le concert", steps: ["Écrase deux rondelles de concombre avec le citron vert dans un grand verre.", "Ajoute des glaçons et le gin, complète au tonic, la dernière rondelle dessus."] },
    zincNoir: { name: "Zinc noir", steps: ["Remue le whisky de seigle, la liqueur de café, l'amaro et l'amer avec des glaçons.", "Filtre sur un gros glaçon."] },
    banquetteArriere: { name: "Banquette arrière", steps: ["Verse le rhum, le nectar de pêche et le citron sur des glaçons.", "Complète à la ginger beer."] },
    rendezVous: { name: "Rencard", steps: ["Secoue le gin, la liqueur de framboise, le citron et le sirop avec des glaçons.", "Filtre dans une coupe, une framboise si tu en as."] },
    pistedeDanse: { name: "Piste de danse", steps: ["Verse la vodka, la liqueur de melon et le citron vert sur des glaçons.", "Complète à la limonade."] },
    vestiaire: { name: "Vestiaire", steps: ["Verse le calvados et le jus de pomme sur des glaçons.", "Complète au ginger ale, une pincée de cannelle."] },
    premierVerre: { name: "Premier verre", steps: ["Verse le quinquina et le pamplemousse sur des glaçons.", "Complète au tonic, léger pour commencer."] },
    bisSurLeZinc: { name: "Bis sur le zinc", steps: ["Remue le mezcal, le bitter et le vermouth avec des glaçons.", "Filtre sur un gros glaçon, zeste d'orange."] },
    crewSour: { name: "Sour du crew", steps: ["Secoue le pisco, la passion, le citron vert, le sirop et le blanc d'œuf sans glace.", "Secoue encore avec des glaçons et filtre dans une coupe."] },
    lampadaire: { name: "Lampadaire", steps: ["Frotte le basilic au fond d'un grand verre.", "Ajoute des glaçons, le limoncello et le gin, complète à l'eau gazeuse."] },
    terrasseEte: { name: "Terrasse d'été", steps: ["Mets les fraises coupées et le sirop de sureau dans un verre à vin.", "Ajoute des glaçons, le rosé et l'eau gazeuse."] },
    chaussettesMouillees: { name: "Chaussettes mouillées", steps: ["Fais chauffer le jus de pomme avec la cannelle et le miel.", "Verse dans une tasse sur le whisky, pour se réchauffer après la pluie."] },
