    selfieMule: { name: "Mule photo", steps: ["Verse la vodka, la passion et le citron vert sur des glaçons.", "Complète à la ginger beer."] },
    cheersPommes: { name: "Santé normande", steps: ["Verse le calvados au fond d'un verre.", "Complète au cidre brut bien frais."] },
    grandeTablee: { name: "Grande tablée", steps: ["Mélange le vin, le cassis et le jus d'orange dans une carafe avec les rondelles d'orange.", "Ajoute des glaçons et le ginger ale au moment de servir."] },
    coupDeFoudre: { name: "Coup de foudre", steps: ["Écrase les fraises et le basilic avec le sirop dans le shaker.", "Ajoute le gin, le citron et des glaçons, secoue, filtre deux fois."] },
    pluieDEte: { name: "Pluie d'été", steps: ["Frotte la menthe avec le sirop de sureau et le citron vert.", "Ajoute des glaçons et le rhum, complète à l'eau gazeuse."] },
    cartePostale: { name: "Carte postale", steps: ["Secoue le rhum coco, la mangue et le citron vert avec des glaçons.", "Verse dans un grand verre et ajoute un trait d'eau gazeuse."] },
    rideauRouge: { name: "Rideau rouge", steps: ["Secoue le gin, le bitter, la liqueur de cerise et le citron avec des glaçons.", "Filtre dans une coupe."] },
    cabine: { name: "Cabine", steps: ["Mélange le bourbon, le miel et le citron dans un verre à shot.", "À trinquer à deux, en face."] },
    feuxDeBengale: { name: "Feux de Bengale", steps: ["Verse le whisky à la cannelle dans un verre à shot froid.", "Ajoute le cranberry, sans remuer."] },
