    blancheNuit: { name: "Blanche de nuit", steps: ["Verse le sirop de sureau au fond du verre.", "Complète à la bière blanche, une rondelle de citron."] },
    stoutDuDimanche: { name: "Stout du dimanche", steps: ["Verse la liqueur de café et la vanille au fond d'un verre.", "Complète au stout, doucement."] },
    mojitoDuToit: { name: "Mojito des toits", steps: ["Écrase le basilic avec le miel et le citron vert.", "Ajoute le rhum et de la glace pilée, complète à l'eau gazeuse."] },
    nuitTropicale: { name: "Nuit tropicale", steps: ["Secoue le rhum agricole, la passion, l'orgeat et le citron vert avec des glaçons.", "Verse sur de la glace pilée."] },
    quaiDeGare: { name: "Quai de gare", steps: ["Remue le cognac, la gentiane et le vermouth avec des glaçons.", "Filtre dans une coupe."] },
    lumiereNoire: { name: "Lumière noire", steps: ["Verse le gin, le curaçao et le citron sur des glaçons.", "Complète au tonic, il brille sous les néons."] },
    souvenirFlou: { name: "Souvenir flou", steps: ["Secoue la vodka, la liqueur de pêche, le pamplemousse et le citron avec des glaçons.", "Filtre dans une coupe."] },
    dancefloorSpritz: { name: "Spritz de la piste", steps: ["Verse le limoncello et l'apéritif à l'orange sur des glaçons.", "Complète au prosecco et à l'eau gazeuse."] },
    laClefDesChamps: { name: "La clé des champs", steps: ["Secoue le gin, la chartreuse, le citron vert et le miel avec des glaçons.", "Filtre dans une coupe froide."] },
    derniereDanse: { name: "Dernière danse", steps: ["Remue le bourbon, le porto, la liqueur de cerise et l'amer avec des glaçons.", "Filtre sur un gros glaçon."] },
    karaoke: { name: "Karaoké", steps: ["Verse la tequila, la mangue et le citron vert sur des glaçons avec la rondelle de piment.", "Complète à l'eau gazeuse."] },
    brunchDuLendemain: { name: "Brunch du lendemain", steps: ["Écrase légèrement le basilic avec le citron et le sel.", "Ajoute le gin et le jus de tomate, verse sur des glaçons."] },
    cafeDuMatin: { name: "Café du matin", steps: ["Verse le sirop de gingembre et le tonic sur des glaçons.", "Fais couler le café dessus, un zeste de citron."] },
    designatedDriver: { name: "Le volant", steps: ["Secoue l'ananas, la passion et le citron vert avec des glaçons.", "Verse dans un grand verre et complète à la ginger beer, menthe dessus."] },
    eauDeLaPiste: { name: "Eau de la piste", steps: ["Écrase le concombre avec le sirop de sureau et le citron vert.", "Ajoute des glaçons et complète à l'eau gazeuse."] },
    roseDesVents: { name: "Rose des vents", steps: ["Verse le pamplemousse et le sirop de framboise sur des glaçons.", "Complète au tonic."] },
    petitMatin: { name: "Petit matin", steps: ["Verse l'orange, la mangue et l'eau de coco sur des glaçons.", "Presse le quartier de citron vert dedans."] },
    cocktailDuCapitaine: { name: "Cocktail du capitaine de soirée", steps: ["Secoue la pomme, la pêche, le citron et la cannelle avec des glaçons.", "Verse dans un grand verre et complète à l'eau gazeuse."] },
